@PostMapping("/queryShareInfoList.do")
    @ApiOperation("出单员查询询价分享列表信息")
    public GenericRpcResponse queryShareInfoList(@RequestHeader("userId") String userId, @RequestHeader("appCode") String appCode, @RequestBody QueryShareInfoListReqDTO queryShareInfoListReqDTO) {
        try {
            log.info("出单员查询询价分享列表信息 - ->userId：{},appCode：{},RequestBody:{}", userId, appCode, JSON.toJSONString(queryShareInfoListReqDTO));

            //获取用户明细
            UserInfoVO userInfoVO = userInfrastructure.queryOneselfInfo(userId, appCode);
            if (userInfoVO == null) {
                return GenericRpcResponse.fail(null, ErrorEnum.ECLIPSE_FRONT_ERROR_CERT_NO.getErrorCode());
            }
            //设置用户id与类型
            queryShareInfoListReqDTO.setOperatorCode(userId);

            Response<PaginationDTO<QueryShareInfoListResDTO>> reposeDTOResponse = vehicleOnlineInfrastructure.queryShareInfoList(queryShareInfoListReqDTO);

            log.info("出单员查询询价分享列表信息 - ->{}", JSON.toJSONString(reposeDTOResponse));

            if (reposeDTOResponse.isSuccess()) {
                return GenericRpcResponse.success(reposeDTOResponse.getContent());
            } else {
                return GenericRpcResponse.fail(reposeDTOResponse.getRespCode(), reposeDTOResponse.getFailCause(), null);
            }
        } catch (Exception e) {
            log.error(e.getMessage(), e);
            return GenericRpcResponse.fail(null, e.getMessage());
        }
    }

@Override
    public UserInfoVO queryOneselfInfo(String userId, String appCode) {
        List<UserInfoDO> list = userInfoMapper.listOwnUsers(Long.valueOf(userId), appCode);
        if (list.isEmpty()) {
            return null;
        }
        return convertUserInfoVO(list.get(0));
    }

